export const sourcePages = {
  "108": "<h2>108</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">19世紀のヨーロッパ文化</strong></span></h1>\n<p>政治史が一段落したから、今回は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">19世紀のヨーロッパ文化史</strong></u>を見ていこう。バラバラに見える文化史も、全体的な時代の動きとしっかりつなげると、社会全体の動きが見えてくるよ！</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文学</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">芸術</strong></span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">古典主義</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">109〜110ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">ロマン主義</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">110〜112ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">写実主義・自然主義</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">112〜115ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span></td><td><strong class=\"source-bold\">印象派・後期印象派</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">115〜116ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span></td><td><strong class=\"source-bold\">社会科学・哲学</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">117〜121ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">6</strong></span></td><td><strong class=\"source-bold\">自然科学・科学技術</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">121〜123ページ</span></td></tr></tbody></table></div>\n<blockquote><p>文学と芸術は分類が似ているけど、後半になるとちょっと違うから気をつけてね！</p></blockquote>\n<p>19世紀になると、絶対王政の時代が終わって<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">近代的な市民社会へと変わった</strong></u>ヨーロッパでは、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">文化の担い手も市民に変わった</strong></u>よ。「市民」と一言でいってもいろいろな人たちがなかに含まれているから、簡単にはまとめられないけど、時期によっていろんな<ruby>流行<rt>はや</rt></ruby>りはある！ 「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">古典主義</strong></u>」「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ロマン主義</strong></u>」「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">写実主義</strong></u>」「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">自然主義</strong></u>」、そして芸術では「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">印象派</strong></u>」という大きな時代の変化を、政治史や社会史とつなげて見ていこう。単なる丸暗記じゃなくて、文化史こそしっかりと理解してほしいな。人名だけを並べてるだけじゃダメよ。</p>\n<p>それじゃあ、19世紀のヨーロッパ文化史、いってみよう〜。</p>",
  "109": "<h2>109</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">古典主義</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">古典主義</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">古典主義って？ 理想はギリシア・ローマ。何事もバランスが大事</strong></span></h4>\n<p><strong class=\"source-bold\">18世紀</strong>までのヨーロッパは<strong class=\"source-bold\">絶対王政</strong>の時代で、文化の中心にいたのは国王や貴族などの特権階級だから、金ピカで豪華にした<strong class=\"source-bold\">バロック様式</strong>や繊細で華麗な<strong class=\"source-bold\">ロココ様式</strong>などが好まれていたよね。どっちもお金がかかるけど。ところが、少しずつ<strong class=\"source-bold\">市民階級が力をつけ始める</strong>と、「今の世の中なんか変だよな？」って疑問が出てきて、伝統的に正しいと考えていたこと、例えば「国王はエライ」とか「教会は正しい」みたいなことに対する批判が始まったんだよ。その根拠とされたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>啓蒙<rt>けいもう</rt></ruby>思想</strong></span>だ。<strong class=\"source-bold\">人間の理性を絶対</strong>と考えて「理性に基づいて判断したことが正しい」っていう<strong class=\"source-bold\">合理主義</strong>により、<strong class=\"source-bold\">絶対王政や教会の腐敗・矛盾を批判</strong>し、教会の権威も伝統的な身分制度も関係なく、自由な個人を中心にものを考えてみよう、ってことになったんだ。</p>\n<p>こういう風潮が文化にどう影響するんだろう？ <strong class=\"source-bold\">自由な個人の人間性を重視</strong>して、理想の人間像を追及していたのは古代ギリシア。それじゃあ、<strong class=\"source-bold\">古代ギリシアを模範</strong>にしよう！っていう<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">古典主義</strong></span>が現れた。ちなみに、ヨーロッパで<strong class=\"source-bold\">古典</strong>（<strong class=\"source-bold\">classic</strong>）っていうと、<strong class=\"source-bold\">ギリシア・ローマ</strong>のことだ。だから、古典主義とは<strong class=\"source-bold\">古代ギリシア・ローマ文化を理想</strong>として<strong class=\"source-bold\">調和の取れた人間性</strong>を重んじる風潮だ。文学なら理性と感情のバランスが、芸術なら全体的に均整のとれた理想の人間像を描くってことになるね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">文学では自然な感情を、芸術では均整のとれた美しさを表現！</strong></span></h4>\n<p>文学では、すでに17世紀のフランスでラシーヌやモリエールらが古典主義演劇をつくっていたけど、<strong class=\"source-bold\">18世紀末のドイツ</strong>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゲーテ</strong></span>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シラー</strong></span>を中心に<strong class=\"source-bold\">人間の自然な感情</strong>を描こうとする<strong class=\"source-bold\"><ruby>疾風怒濤<rt>しっぷうどとう</rt></ruby>運動【シュトゥルム＝ウント＝ドランク】</strong>が起きた。例えば、有名な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゲーテ</strong></span>の『<strong class=\"source-bold\">若きウェルテルの悩み</strong>』は、初恋相手に再会したことで恋心が復活した主人公ウェルテルが、彼女の結婚を知って、「自分の恋心」と「結婚する彼女に手を出しちゃいけない」という理性の間で揺れ動き、ついには自殺しちゃう、って話だ。ゲーテはのちの<strong class=\"source-bold\">ロマン主義の先駆者</strong>になったんだけど、フランス革命には否定的で、晩年は<strong class=\"source-bold\">古典主義</strong>に傾いたんだ。</p>\n<blockquote><p>ヴァルミーの戦いでプロイセン軍に従軍していたゲーテは、「世界史の新しい時代が始まる」って記しているよ</p></blockquote>\n<p>芸術では<strong class=\"source-bold\">ナポレオン1世の<ruby>宮廷<rt>きゅうてい</rt></ruby>画家</strong>だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダヴィド</strong></span>や、その弟子の<strong class=\"source-bold\">アングル</strong>などによって、<strong class=\"source-bold\">均整のとれた美しさ</strong>を重視する絵が描かれたね。要するにギリシア彫刻みたいに理想的な人間を描こうってことだ。特にダヴィドは<strong class=\"source-bold\">ナポレオンを英雄として描いた</strong>多くの絵で有名だね。ルーブル美術館にある大作「<strong class=\"source-bold\">ナポレオンの<ruby>戴冠式<rt>たいかんしき</rt></ruby></strong>」はなんと縦6m、横9mもあるよ。</p>",
  "110": "<h2>110</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span> 19世紀のヨーロッパ文化</p>\n<p>音楽は<strong class=\"source-bold\">ドイツが中心</strong>だよ。100曲以上もの<ruby>交響曲<rt>こうきょうきょく</rt></ruby>を作曲して「<strong class=\"source-bold\">交響曲の父</strong>」と呼ばれる<strong class=\"source-bold\">ハイドン</strong>、<strong class=\"source-bold\">マリアントワネットとほぼ同時代</strong>にあたる音楽の天才<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モーツァルト</strong></span>、9つの重厚な交響曲で不動の地位を築いた<strong class=\"source-bold\">ボン出身</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベートーヴェン</strong></span>が<strong class=\"source-bold\">古典派</strong>にあたるよ。政治史と関係する話だと、ベートーヴェンの<strong class=\"source-bold\">交響曲第3番</strong>「英雄」は、もともと<strong class=\"source-bold\">ナポレオンのためにつくった</strong>んだけど、彼が皇帝になったのに失望したベートーヴェンが表紙を破り捨てた、といわれている。</p>\n<h3><strong class=\"source-bold\">〈<ruby>疾風怒濤<rt>しっぷうどとう</rt></ruby>運動→古典主義文学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>独</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゲーテ</strong></span></td><td>『<strong class=\"source-bold\">若きウェルテルの悩み</strong>』『ファウスト』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シラー</strong></span></td><td>『<strong class=\"source-bold\"><ruby>群盗<rt>ぐんとう</rt></ruby></strong>』『ワレンシュタイン』</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈古典主義絵画〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダヴィド</strong></span></td><td>「<strong class=\"source-bold\">ナポレオンの<ruby>戴冠式<rt>たいかんしき</rt></ruby></strong>」。<strong class=\"source-bold\">ナポレオン1世の<ruby>宮廷<rt>きゅうてい</rt></ruby>画家</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">アングル</strong></td><td>ダヴィドの弟子。「グランド＝オダリスク」</td></tr></tbody></table></div>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ロマン主義</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">革命によって高まった自由主義・ナショナリズム。でも<ruby>弾圧<rt>だんあつ</rt></ruby>されて……</strong></span></h4>\n<p>18世紀末から19世紀初めは<strong class=\"source-bold\">フランス革命とナポレオンの時代</strong>だよね。フランス革命では「<strong class=\"source-bold\">自由・平等・友愛</strong>」をスローガンに王政を打倒し、市民が権利を勝ち取り、さらにフランス人は「<strong class=\"source-bold\">祖国フランス</strong>」っていう意識を持ち始めた。この<strong class=\"source-bold\">自由主義・ナショナリズム</strong>（<strong class=\"source-bold\">国民主義</strong>）がヨーロッパ全体に広がって、文化にも影響するんだよ。</p>\n<p>こうして、18世紀の<ruby>啓蒙<rt>けいもう</rt></ruby>思想や古典主義に対して「これからは理性よりも<strong class=\"source-bold\">自由な感情</strong>だ♪」とか、「調和よりも<strong class=\"source-bold\">個性</strong>の時代だ！」って考える風潮が現れた。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロマン主義</strong></span>だよ。じゃあ、なんでこんな考え方が広がったんだろ？ 19世紀前半といえばウィーン体制のもとで<strong class=\"source-bold\">自由主義やナショナリズムが弾圧</strong>されていたから、人びとが自由を求める傾向が強かったよね。これが文化に結びつくと、<strong class=\"source-bold\">個人の自由</strong>に加えて、それぞれの<strong class=\"source-bold\">民族の歴史や伝統に基づく独自性</strong>を重視する傾向が生まれたんだ。じゃあ、ヨーロッパで各民族の独自性が生まれたのはいつだろう？ 古典主義が理想とした<strong class=\"source-bold\">ローマは「世界帝国」</strong>だから、むしろ「普遍」。そのあと、<strong class=\"source-bold\">ヨーロッパ各国の原型が出現したのは中世</strong>だよね。ってことで、ロマン主義では<strong class=\"source-bold\">中世やルネサンスが理想</strong>とされたんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">自由主義・ナショナリズムと結びついた絵や音楽がつくられた</strong></span></h4>\n<p>じゃあ、<strong class=\"source-bold\">芸術</strong>の分野から見ていこう。絵画では<strong class=\"source-bold\">フランス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドラクロワ</strong></span>が、調和を破った<strong class=\"source-bold\">情熱的な激しい色使い</strong>で、<strong class=\"source-bold\">ギリシア独立戦争</strong>を題材にした「<strong class=\"source-bold\">キオス島の<ruby>虐<rt>ぎゃく</rt></ruby><ruby>殺<rt>さつ</rt></ruby></strong>」や、<strong class=\"source-bold\">七月革命</strong>を題材にした「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民衆を導く自由の<ruby>女神<rt>めがみ</rt></ruby></strong></span>」などを描いた。さらに音</p>",
  "111": "<h2>111</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロマン主義</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>楽では、<strong class=\"source-bold\">ポーランド</strong>の国民意識を背景に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ショパン</strong></span>がエチュード「<strong class=\"source-bold\">革命</strong>」を作曲したり、ドイツの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴァーグナー</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワグナー</strong></span>】は<strong class=\"source-bold\">楽劇</strong>を創始し、中世ドイツの「ニーベルンゲンの歌」を題材に大作「<strong class=\"source-bold\">ニーベルングの指環</strong>」をつくったりしたね。そして、ロマン主義から派生して、<strong class=\"source-bold\">伝統的な民族音楽などをもとにした</strong>民族性あふれる<strong class=\"source-bold\">国民楽派音楽</strong>も現れたよ。バレエ音楽「くるみ割り人形」で有名なロシアの<strong class=\"source-bold\">チャイコフスキー</strong>や、交響詩「わが祖国」をつくったチェコの<strong class=\"source-bold\">スメタナ</strong>などが代表だ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">文学では感情の高まりと民族の伝統がキーワードだ</strong></span></h4>\n<p>文学では、<strong class=\"source-bold\">個人の感情の高まり</strong>や<strong class=\"source-bold\">民族の伝統を表現</strong>する作品が多数つくられた。<strong class=\"source-bold\">ドイツ</strong>での注目ポイントは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">グリム兄弟</strong></span>。彼らはドイツ民族の伝統、要は<strong class=\"source-bold\">ドイツ語の研究</strong>をやった。政治的にはバラバラだけど、みんなが話しているドイツ語の研究を通じて<strong class=\"source-bold\">ドイツ文化とは何か</strong>を明らかにしたかったんだね。だから、最終的な目標は『<strong class=\"source-bold\">ドイツ語辞典</strong>』をつくる！ そのために集めたドイツ各地の昔話を『子どもと家庭のための童話集（<strong class=\"source-bold\">グリム童話集</strong>）』にまとめてみたよ。さらに、<strong class=\"source-bold\">ユダヤ系</strong>だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハイネ</strong></span>は<strong class=\"source-bold\">マルクスとも親交</strong>を持ったから、「<strong class=\"source-bold\">革命詩人</strong>」と呼ばれているね。</p>\n<p><strong class=\"source-bold\">フランス</strong>のロマン主義といえば<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴー</strong></span>だ。彼の書いた超大作『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レ＝ミゼラブル</strong></span>』は、映画やミュージカルにもなっているから知ってるかな？ 彼は政治的には<strong class=\"source-bold\">二月革命後に共和派</strong>となり、<strong class=\"source-bold\">ナポレオン3世の第二帝政を批判</strong>したから18年間も<ruby>亡<rt>ぼう</rt></ruby><ruby>命<rt>めい</rt></ruby>生活を送り、この時に『レ＝ミゼラブル』がつくられたんだよ。この作品の中には、労働者の<ruby>堕落<rt>だらく</rt></ruby>、飢えが原因の女性の転落、そして子どもの破滅など、<strong class=\"source-bold\">社会で「<ruby>虐<rt>しいた</rt></ruby>げられた人びと」を人道的に救おう！</strong>というメッセージが込められている。</p>\n<p>そのほか、<strong class=\"source-bold\">ギリシア独立戦争に<ruby>義勇軍<rt>ぎゆうぐん</rt></ruby>として参戦</strong>した<strong class=\"source-bold\">イギリス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バイロン</strong></span>は、もう生き方そのものがロマン主義。アメリカの<strong class=\"source-bold\">ホイットマン</strong>はアメリカの自然や自由と民主主義を<ruby>讃<rt>たた</rt></ruby>える『<strong class=\"source-bold\">草の葉</strong>』で有名だね。</p>\n<p>こんなふうに、ロマン主義の作品には、<strong class=\"source-bold\">自分の民族を讃えるものが多かった</strong>ってことだ。反面、民族を理想化しすぎたり、個性を重視しすぎるあまり、ちょっと現実離れしてしまうこともあったんだね。</p>\n<h3><strong class=\"source-bold\">〈ロマン主義絵画〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドラクロワ</strong></span></td><td>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民衆を導く自由の女神</strong></span>」「<strong class=\"source-bold\">キオス島の虐殺</strong>」</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈ロマン主義音楽〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>墺</td><td><strong class=\"source-bold\">シューベルト</strong></td><td>「冬の旅」などの歌曲で有名。「未完成交響曲」</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ショパン</strong></span></td><td><strong class=\"source-bold\">ピアノの詩人</strong>と呼ばれる。エチュード「<strong class=\"source-bold\">革命</strong>」</td></tr><tr><td>露</td><td><strong class=\"source-bold\">チャイコフスキー</strong></td><td>ロマン主義から派生した<strong class=\"source-bold\">国民楽派</strong>の影響。<strong class=\"source-bold\">バレエ音楽</strong>が有名</td></tr><tr><td>独</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴァーグナー</strong></span></td><td><strong class=\"source-bold\">楽劇</strong>を創始。「タンホイザー」「<strong class=\"source-bold\">ニーベルングの指環</strong>」</td></tr><tr><td></td><td><strong class=\"source-bold\">スメタナ</strong></td><td><strong class=\"source-bold\">チェコ国民楽派の祖</strong>。交響詩「わが祖国」（第2曲の「モルダウ」が有名）</td></tr></tbody></table></div>",
  "112": "<h2>112</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span> 19世紀のヨーロッパ文化</p>\n<h3><strong class=\"source-bold\">〈ロマン主義文学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>独</td><td><em data-source-italic=\"true\" style=\"font-style:italic\"><strong class=\"source-bold\">ノヴァーリス</strong></em></td><td>『青い花』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">グリム兄弟</strong></span></td><td>『<strong class=\"source-bold\">ドイツ語辞典</strong>』『子どもと家庭のための童話集（<strong class=\"source-bold\">グリム童話集</strong>）』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハイネ</strong></span></td><td>『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">歌の本</strong></span>』。<strong class=\"source-bold\">マルクスとも親交</strong>を持ち、「<strong class=\"source-bold\">革命詩人</strong>」と呼ばれる</td></tr><tr><td>仏</td><td>スタール夫人</td><td>ネッケルの娘。ドイツ＝ロマン主義をフランスに紹介</td></tr><tr><td></td><td>シャトーブリアン</td><td>『アタラ』『ルネ』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ユーゴー</strong></span></td><td>『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レ＝ミゼラブル</strong></span>』</td></tr><tr><td>英</td><td>ワーズワース</td><td>『叙情詩選』。人間と自然の調和を説く</td></tr><tr><td></td><td>スコット</td><td>物語詩『湖上の美人』歴史小説『アイヴァンホー』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バイロン</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシア独立戦争</strong></span>に参戦。『チャイルド＝ハロルドの<ruby>巡礼<rt>じゅんれい</rt></ruby>』</td></tr><tr><td>米</td><td>ホーソン</td><td>『<ruby>緋文字<rt>ひもんじ</rt></ruby>』。ピューリタン文学</td></tr><tr><td></td><td><strong class=\"source-bold\">ホイットマン</strong></td><td>詩集『<strong class=\"source-bold\">草の葉</strong>』</td></tr><tr><td>露</td><td><strong class=\"source-bold\">プーシキン</strong></td><td>『<ruby>大尉<rt>たいい</rt></ruby>の娘』『オネーギン』。ヒューマニズムから専制政治を批判</td></tr></tbody></table></div>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">写実主義・自然主義</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ロマン主義は非現実的。現実はもっとひどいよ……</strong></span></h4>\n<p>19世紀半ばには<strong class=\"source-bold\">各国で産業革命が始まり</strong>、少しずつ<strong class=\"source-bold\">資本主義経済が発達</strong>してきたよね。産業資本家の成長によって<strong class=\"source-bold\">市民社会が成熟</strong>してくると、あまりにも現実離れした作品は好まれなくなってくる。さらに、<strong class=\"source-bold\">労働者階級の増加</strong>による<strong class=\"source-bold\">都市の生活環境や労働環境の悪化</strong>や、発展から取り残された<strong class=\"source-bold\">農村部との<ruby>貧富<rt>ひんぷ</rt></ruby>の格差</strong>も問題だ。こういった社会問題が大きくなってくると、そこから目を<ruby>背<rt>そむ</rt></ruby>けるわけにもいかなくなってきた。しかも、<strong class=\"source-bold\">自然科学や科学技術の発達</strong>によって、科学的なものの見方が広がってくる。科学技術に感情はないでしょ？ もはや夢ばかり見ているわけにもいかない。</p>\n<p>こうして、非現実的なロマン主義にかわって、<strong class=\"source-bold\">人間や社会のありのままの姿を客観的に描こう</strong>とする傾向がでてきたよ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">写実主義</strong></span>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自然主義</strong></span>だ。ただこの2つの言葉、<strong class=\"source-bold\">文学と芸術でちょっとニュアンスが違う</strong>から気をつけてね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">絵画では、都市を題材にした「写実主義」、農村を題材にした「自然主義」だ</strong></span></h4>\n<p>この時代の絵画に影響を与えたものとして、<strong class=\"source-bold\">カメラの発明</strong>があるよ。19世紀にはある意味で「<strong class=\"source-bold\">ありのまま」の姿を写真に残すことができる</strong>ようになった。画家たちにとってはライバルだね。ロマン主義の絵画では<ruby>誇張<rt>こちょう</rt></ruby>や<ruby>幻想<rt>げんそう</rt></ruby>が多くあったけど、もはやそんなものはいらない。だから、<strong class=\"source-bold\">ありのままの姿を絵に描こう</strong>としたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自然主義</strong></span>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">写実主義</strong></span>だよ。ただ両者は、題材が少し違うんだ。おもに<strong class=\"source-bold\">農村や自然を題材にした自然主義</strong>、<strong class=\"source-bold\">都市市民を題材にした写実主義</strong>って覚えておこう！</p>",
  "113": "<h2>113</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">写実主義・自然主義</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>しかも、もう1つの衝撃がある！ それが絵の「サイズ」。これまで2mや3mといった絵は、国王や貴族、あるいは神を描く時のサイズだったんだけど、単なる民衆の絵にそれだけのサイズを与えたから、それだけで衝撃だったんだよ。</p>\n<p>まずは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自然主義</strong></span>。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミレー</strong></span>とその仲間の画家たちは、七月革命後の貧乏生活もあって、パリ近郊のフォンテーヌブローの森のはずれにある<strong class=\"source-bold\">バルビゾン村に集まった</strong>から<strong class=\"source-bold\">バルビゾン派</strong>とも呼ばれている。ここで<strong class=\"source-bold\">農民の生活や自然を題材</strong>に創作をしたんだ。特にミレーの「<strong class=\"source-bold\"><ruby>落穂<rt>おちぼ</rt></ruby>拾い</strong>」は有名だよ。</p>\n<blockquote><p>▲ミレー「落穂拾い」</p></blockquote>\n<p>一方の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">写実主義</strong></span>は、<strong class=\"source-bold\">都市の下層労働者が題材</strong>になったんだけど、下層労働者に接近するということは、同じ時代に出現した<strong class=\"source-bold\">社会主義に接近</strong>するということだ。<strong class=\"source-bold\">ドーミエ</strong>はたくましく生きる都市市民の様子を描き、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クールベ</strong></span>は最下層民衆の労働の様子を「<strong class=\"source-bold\">石割り</strong>」などに描くとともに、同郷の友人だったプルードンの影響もあって<strong class=\"source-bold\">社会主義に接近</strong>、<strong class=\"source-bold\">パリ＝コミューンに参加</strong>したけど<ruby>挫折<rt>ざせつ</rt></ruby>して、<ruby>禁固刑<rt>きんこけい</rt></ruby>になったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">現実を直視したけど……まだちょっとは救いがある写実主義文学</strong></span></h4>\n<p>文学ではロマン主義のような<strong class=\"source-bold\">人道的な要素が薄れてしまう</strong>んだよ。というのも、誰が見ても下層民衆の生活はひどい！ <strong class=\"source-bold\">資本主義の発達による貧富の格差の問題</strong>にロマンなんかあるわけがない！ だから、客観的に「現実を見ろ〜」って風潮が強まったんだ。こうして、<strong class=\"source-bold\">人生の現実から目を背けず、ありのままに描こう</strong>とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">写実主義</strong></span>が現れたんだよ。</p>\n<p><strong class=\"source-bold\">フランス</strong>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スタンダール</strong></span>が<strong class=\"source-bold\">貴族（赤）と聖職者（黒）などの特権階級</strong>に敵意を持つ少年ジュリアンを主人公とする『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">赤と黒</strong></span>』を書いたよ。主人公の少年は、特権階級の奥さんとの不倫や娘との結婚でのし上がろうとするんだけど、成功の寸前に殺人を犯して死刑判決を受ける。ただ、最後に真実の愛を知る……みたいな。</p>\n<p>こんなふうに、写実主義って<strong class=\"source-bold\">最後にはなんとなく救いがある</strong>。現実はひどい話なんだけど、読み終わった時に「まぁ良かったかもな」っていう感じね。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルザック</strong></span>の『<strong class=\"source-bold\">人間喜劇</strong>』は、彼が20年にわたって書いた90編以上の小説の総称で、貴族の没落、新興ブルジョワの台頭、家族制度の崩壊など、当時のフランス社会が見事に分析され、話によってはかなり批判的なものもあるよ。</p>\n<p><strong class=\"source-bold\">イギリス</strong>では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディケンズ</strong></span>が<strong class=\"source-bold\">フランス革命期のロンドンとパリを舞台にした</strong>『<ruby>二<rt>に</rt></ruby><ruby>都<rt>と</rt></ruby>物語』を書いたよ。主人公は貴族身分を捨ててパリに戻って革命に参加しようとしたら恐怖政治のもとで捕まり、最後は愛する女性の夫の身代わりになってギロチンにかけられる。これも愛のために死ぬっていう救いがちょっとはあるよね。</p>",
  "114": "<h2>114</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span> 19世紀のヨーロッパ文化</p>\n<p>問題は<strong class=\"source-bold\">ロシア</strong>だよ。ロシアの現実を直視すると、あまりにひどすぎる。まず、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トゥルゲーネフ</strong></span>は、<strong class=\"source-bold\">ロシアの<ruby>農奴<rt>のうど</rt></ruby>のひどい現実</strong>を、ロシアの美しい自然描写のなかに描いた『<strong class=\"source-bold\"><ruby>猟人<rt>りょうじん</rt></ruby>日記</strong>』や、農奴解放後のロシア社会と<strong class=\"source-bold\">無気力になってしまったナロードニキ</strong>を描いた『<strong class=\"source-bold\">父と子</strong>』などを書いたよ。ちなみに『猟人日記』は、これを読んだ<strong class=\"source-bold\">アレクサンドル2世を農奴解放に向かわせた</strong>作品だよ。また、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドストエフスキー</strong></span>は、農民を苦しめる高利貸しの<ruby>婆<rt>ばあ</rt></ruby>さんを、正義のためとして殺害した革命家を主人公にした『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">罪と罰</strong></span>』や、人間の魂の救済を題材とした未完の大作『<strong class=\"source-bold\">カラマーゾフの兄弟</strong>』で有名だ。さらに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルストイ</strong></span>はキリスト教の人道主義の立場から、<strong class=\"source-bold\">ナポレオンのロシア遠征を題材</strong>とした『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦争と平和</strong></span>』などを書くとともに、<strong class=\"source-bold\">人道主義的な反戦運動</strong>をおこなったんだ。</p>\n<p>全体として感じてほしいのは、<strong class=\"source-bold\">写実主義は描かれている現実はひどい</strong>のだけど、最終的には<strong class=\"source-bold\">なんとなく救いがある</strong>ってことね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">行き着くところは……救いのない現実まで描く自然主義文学</strong></span></h4>\n<p>時代が進むと、工業発展とともに<strong class=\"source-bold\">社会矛盾はさらに大きくなっていった</strong>。こうした状況から、<strong class=\"source-bold\">現実をもっと実験的・科学的にとらえ</strong>、「<strong class=\"source-bold\">救えないものは救えない！</strong>」というところまで強調してしまったのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自然主義</strong></span>だよ。もはや、写実主義のような「最後はまぁよかったかな」という感覚はなくなってしまうよ。</p>\n<p><strong class=\"source-bold\">フランス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゾラ</strong></span>は<strong class=\"source-bold\">自然主義を確立</strong>した作家だよ。彼の代表作『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">居酒屋</strong></span>』はひどいなんてもんじゃない！ 多少の貯金もあって、下層労働者としては幸せに暮らしていたブリキ職人と洗濯女の夫婦が、ダンナが足をケガして仕事ができなくなったのをきっかけに<ruby>堕落<rt>だらく</rt></ruby>し、アル中で頭がおかしくなって死亡、奥さんもアル中で発狂してほぼ<ruby>餓死<rt>がし</rt></ruby>……。もはや、<strong class=\"source-bold\">話になんの救いもない</strong>でしょ……これが自然主義だよ。ちなみにゾラは、<strong class=\"source-bold\">ドレフュス事件で軍部を批判</strong>したことでも有名だよ。ほかに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モーパッサン</strong></span>の『<strong class=\"source-bold\">女の一生</strong>』も、ダンナの家庭内暴力と不倫に苦しむ奥さんが、さらに過保護からわがまま放題になった息子に金をせびられる……という、救いようのない女性の一生を描いた作品だ。</p>\n<p><em data-source-italic=\"true\" style=\"font-style:italic\"><strong class=\"source-bold\">ノルウェー</strong></em>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イプセン</strong></span>は戯曲（演劇の脚本）『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人形の家</strong></span>』で、無理解なダンナから逃れるために家を出たノラを主人公に、女性一人で生きていく苦労を描き<strong class=\"source-bold\">女性解放運動への展望を示した</strong>。これならちょっとは救いがあるかもね。</p>\n<p>こんなふうに、19世紀後半には写実主義・自然主義という、<strong class=\"source-bold\">現実を直視する文学が主流になった</strong>ってことだね。でも、こんな作品ばかりじゃだんだんイヤになってくる……。だから、<strong class=\"source-bold\">世紀末</strong>には善悪を一切無視して美を最高の価値とする<strong class=\"source-bold\"><ruby>耽<rt>たん</rt></ruby><ruby>美<rt>び</rt></ruby>主義</strong>や、言葉のリズムや<ruby>象徴<rt>しょうちょう</rt></ruby>的な表現を多く使う<strong class=\"source-bold\">象徴主義</strong>が現れたんだよ。耽美主義には、『悪の華』を書いた<strong class=\"source-bold\">ボードレール</strong>（仏）や『サロメ』を書いたワイルド（英）、象徴主義には『秋の歌』を書いた<strong class=\"source-bold\">ヴェルレーヌ</strong>（仏）などがいるよ。また、科学の発達を背景に、<strong class=\"source-bold\">ヴェルヌ</strong>（仏）の『海底二万里』、<strong class=\"source-bold\">ウェルズ</strong>（英）『タイムマシン』などの<strong class=\"source-bold\">SF小説</strong>も生まれたんだ。</p>",
  "115": "<h2>115</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">印象派・後期印象派</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h3><strong class=\"source-bold\">〈自然主義絵画〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミレー</strong></span></td><td>「<strong class=\"source-bold\"><ruby>落穂<rt>おちぼ</rt></ruby>拾い</strong>」「<strong class=\"source-bold\"><ruby>晩鐘<rt>ばんしょう</rt></ruby></strong>」。<strong class=\"source-bold\">バルビゾン派</strong>を形成</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈写実主義絵画〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>仏</td><td><strong class=\"source-bold\">ドーミエ</strong></td><td>「三等列車」。<strong class=\"source-bold\">革命と共和政を支持</strong></td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クールベ</strong></span></td><td>「<strong class=\"source-bold\">石割り</strong>」。<strong class=\"source-bold\">パリ＝コミューンに参加</strong></td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈写実主義文学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スタンダール</strong></span></td><td>『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">赤と黒</strong></span>』。<strong class=\"source-bold\">ナポレオン軍の軍人出身</strong></td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルザック</strong></span></td><td>『<strong class=\"source-bold\">人間喜劇</strong>』。市民社会と小市民を題材</td></tr><tr><td></td><td><strong class=\"source-bold\">フロベール</strong></td><td>『ボヴァリー夫人』</td></tr><tr><td>英</td><td><strong class=\"source-bold\">サッカレー</strong></td><td>『<ruby>虚栄<rt>きょえい</rt></ruby>の<ruby>市<rt>いち</rt></ruby>』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディケンズ</strong></span></td><td>『<strong class=\"source-bold\"><ruby>二都<rt>にと</rt></ruby>物語</strong>』『オリヴァー＝トゥイスト』</td></tr><tr><td>露</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トゥルゲーネフ</strong></span></td><td>『<strong class=\"source-bold\">猟人日記</strong>』（農奴制を題材）『<strong class=\"source-bold\">父と子</strong>』（<strong class=\"source-bold\">ナロードニキ</strong>を題材）</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドストエフスキー</strong></span></td><td>『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">罪と罰</strong></span>』『<strong class=\"source-bold\">カラマーゾフの兄弟</strong>』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トルストイ</strong></span></td><td>『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦争と平和</strong></span>』（<strong class=\"source-bold\">ナポレオン戦争</strong>を題材）『アンナ＝カレーニナ』</td></tr><tr><td></td><td>チェーホフ</td><td>『桜の園』</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈自然主義文学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゾラ</strong></span></td><td>『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">居酒屋</strong></span>』『ナナ』。<strong class=\"source-bold\">ドレフュス事件で、軍部を批判</strong></td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モーパッサン</strong></span></td><td>『<strong class=\"source-bold\">女の一生</strong>』</td></tr><tr><td>北欧</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イプセン</strong></span></td><td><em data-source-italic=\"true\" style=\"font-style:italic\"><strong class=\"source-bold\">ノルウェー</strong></em>の作家。『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人形の家</strong></span>』（女性解放運動に影響）</td></tr><tr><td></td><td>ストリンドベリ</td><td>スウェーデンの作家。『父』『令嬢ジュリー』</td></tr></tbody></table></div>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">印象派・後期印象派</strong></span></h3>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">印象派――カメラには勝てなかった画家が、写真とは違う「印象」を描いた！</strong></span></h4>\n<p>写実主義や自然主義は現実をありのままの姿に描こうとしたんだけど、そのまま描くならカメラには勝てない。だから画家たちは違った方向へと向かい始めた。それが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">印象派</strong></span>だよ。印象派は「光」に注目し、<strong class=\"source-bold\">光と影の色彩を自分の印象のままに</strong>、場合によっては<strong class=\"source-bold\">光そのもの</strong>（例えば光の三原色を使って）を描こうとしたんだ。</p>\n<blockquote><p>▲マネ「草上の昼食」</p></blockquote>\n<p>まず、<strong class=\"source-bold\">印象派の画家を支援した</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マネ</strong></span>は、「<strong class=\"source-bold\">草上の昼食</strong>」を発表したよ。これ、当時</p>",
  "116": "<h2>116</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span> 19世紀のヨーロッパ文化</p>\n<p>としては大事件。だって、普通の女性が2人の男性の横で、なぜか全裸。別に裸の女性の絵は珍しくもないけど、これまでの<ruby>裸婦<rt>らふ</rt></ruby>の絵は、<ruby>女神<rt>めがみ</rt></ruby>とか異国情緒とか、とにかく現実離れしている題材だった。それが、マネが描いたのは<strong class=\"source-bold\">そのへんにいる普通の「むちゃくちゃ現実的」な女性が全裸だった</strong>のが大事件！ 「<ruby>不謹慎<rt>ふきんしん</rt></ruby>だ！ 不道徳だ！」とさんざん批判されたよ。</p>\n<p>その後、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モネ</strong></span>が登場して<strong class=\"source-bold\">印象派の画風が確立</strong>されていく。モネは「<strong class=\"source-bold\">印象・日の出</strong>」で、光が刻々と変化するルアーブル港の情景を描いたんだけど、<strong class=\"source-bold\">この作品にちなんで印象派</strong>という名前がついたよ。あとは連作「<strong class=\"source-bold\"><ruby>睡蓮<rt>すいれん</rt></ruby></strong>」が有名だね。そして印象派の巨匠が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルノワール</strong></span>だ。パリの歓楽街モンマルトルのダンスホールを描いた「<strong class=\"source-bold\">ムーラン＝ド＝ラ＝ギャレット</strong>」が代表作だね。彼の作品は輝かしい色彩のものが多く、「<strong class=\"source-bold\">色彩の魔術師</strong>」とも呼ばれているよ。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">ポスト印象派――画家個人の印象から、色や形まで変化させた</strong></span></h4>\n<p>印象派の作風がさらに進むと、いよいよ絵に描く<strong class=\"source-bold\">対象物の形が変化</strong>し始めるよ。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポスト印象派</strong></span>（一般的な呼び名の「<strong class=\"source-bold\">後期印象派</strong>」は訳語の誤り）の最初が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セザンヌ</strong></span>。セザンヌは風景画をベタ塗り（真っ平らに塗っていく）で表現するなど、<strong class=\"source-bold\">自然を単純化</strong>した画風の絵を描いた。彼がよく描いたのが<strong class=\"source-bold\">サント＝ヴィクトワール山</strong>。彼の対象物を単純化した描き方は、のちの<strong class=\"source-bold\">立体派【キュビズム】</strong>につながっていくよ。それから<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴーガン</strong></span>。<strong class=\"source-bold\">晩年にタヒチで暮らした</strong>ゴーガンは、フランスにエキゾチックな異国趣味を広めた。そして、生前には全く評価されなかった<strong class=\"source-bold\">オランダ</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴッホ</strong></span>。<strong class=\"source-bold\"><ruby>渦巻<rt>うずま</rt></ruby>きのようなタッチ</strong>や<strong class=\"source-bold\">現実にはない色を多用する色彩感覚</strong>は、当時の人にはまだ早すぎたんだろうし、彼自身も最後は精神<ruby>錯乱<rt>さくらん</rt></ruby>で自殺してしまう。有名な「<strong class=\"source-bold\">ひまわり</strong>」や、空がグルグル渦を巻いてる「<strong class=\"source-bold\">星月夜</strong>」、赤や緑で塗られた自画像など、現代から見ても新しい画風がわかるよ。こうした描き方は、<strong class=\"source-bold\">感情を作品中に反映させて表現</strong>する手法（<strong class=\"source-bold\">表現主義</strong>）に大きな影響を与えるんだ。それからこの時代のマネ、モネ、ゴッホらは<strong class=\"source-bold\">日本の<ruby>浮世絵<rt>うきよえ</rt></ruby>の構図や画風に大きな影響を受けていた</strong>よ。これを日本趣味（<strong class=\"source-bold\">ジャポニズム</strong>）というんだ。</p>\n<h3><strong class=\"source-bold\">〈印象派絵画〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マネ</strong></span></td><td>「<strong class=\"source-bold\">草上の昼食</strong>」「笛を吹く少年」</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モネ</strong></span></td><td>「<strong class=\"source-bold\">印象・日の出</strong>」「睡蓮」。外光に満ちた風景画</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルノワール</strong></span></td><td>「<strong class=\"source-bold\">ムーラン＝ド＝ラ＝ギャレット</strong>」。女性の裸像も多い</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈ポスト印象派絵画〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セザンヌ</strong></span></td><td><strong class=\"source-bold\">自然を単純化</strong>した画風。「サント＝ヴィクトワール山」</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴーガン</strong></span></td><td><strong class=\"source-bold\">晩年をタヒチで暮らす</strong>。「タヒチの女」</td></tr><tr><td>蘭</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴッホ</strong></span></td><td>「<strong class=\"source-bold\">ひまわり</strong>」「星月夜」。生前には全く評価されず</td></tr></tbody></table></div>",
  "117": "<h2>117</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">社会科学・哲学</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">社会科学・哲学</strong></span></h3>\n<h4><em data-source-italic=\"true\" style=\"font-style:italic\"><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">経済学</strong></span></em></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">経済学は国によって違う！ 発展の仕方で考え方も変わるよ</strong></span></h4>\n<p>それじゃあ<strong class=\"source-bold\">社会科学</strong>に進むよ。まずは<strong class=\"source-bold\">経済学</strong>だ。すでに<strong class=\"source-bold\">市民社会が出現していたイギリス</strong>では、政治的な問題だけではなくて<strong class=\"source-bold\">経済的にも自由を求める動き</strong>が強まっていた。すでに18世紀には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アダム＝スミス</strong></span>が登場して『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">諸国民の富</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国富論</strong></span>】』を書き、「<strong class=\"source-bold\">神の見えざる手</strong>」という言葉で有名な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">自由主義経済学</strong></span>を完成させ、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">古典派経済学</strong></span>を創始した。これは絶対王政時代から特定の商人などが持っていた特権をなくして、<strong class=\"source-bold\">自由放任</strong>が一番いい！っていう理論だよ。このあとも、産業革命が進んだイギリスでは、自由主義を主張する古典派経済学がさらに発展していくよ。</p>\n<p>産業革命によって<strong class=\"source-bold\">下層労働者の<ruby>貧困<rt>ひんこん</rt></ruby></strong>が問題になると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルサス</strong></span>は『<strong class=\"source-bold\">人口論</strong>』を著し、「なぜ貧困が拡大するか？」という問題について「<strong class=\"source-bold\">食糧生産と人口増加のアンバランス</strong>がいけない！」と主張した。大ざっぱに言うと、「人口はかけ算で、食糧生産は足し算で増えていくから、<strong class=\"source-bold\">人口増加に食糧生産が追いつかない</strong>」っていうことだ。少子化が進んでいる現代だとピンとこないかもしれないけど、当時の貧困層は子どもも重要な働き手だった。だから貧乏な人ほど子どもが多かったんだ。さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リカード</strong></span>は、<strong class=\"source-bold\">商品の価値（値段）をその生産に費やされた労働の量（つまり人件費）で決まる</strong>という<strong class=\"source-bold\">労働価値説</strong>を主張した。</p>\n<p>労働価値説を簡単な例にしよう。僕の行きつけのラーメン屋でネギをトッピングすると150円なんだけど、スーパーとかで売ってる150円分のネギは入っていない。そんなに入れたら、どんぶりの中はネギだらけ。じゃあ、なんで150円かっていうと、「ラーメン屋のご主人がネギを切る動きが1回10円、タレを入れて混ぜるのが1回10円」みたいな感じね。手の動きで値段が上がってるわけ。「混ぜるの1回減らして10円安くして！」とは言えないけどさ。</p>\n<p>自由主義を主張するイギリスの古典派経済学に対して、「オマエら発展してるからって、勝手なことを言うな！」って思ったのが<strong class=\"source-bold\">ドイツ人</strong>だ。<strong class=\"source-bold\">自由貿易にしたら、発展しているイギリスが勝つ</strong>に決まっている。当時は文化的にも<strong class=\"source-bold\">ロマン主義の時代</strong>で「民族の伝統や独自性」が重視されていたから、経済学でも「<strong class=\"source-bold\">各国の発展の段階に応じて（経済の発展段階説）</strong>、とるべき政策は違う！」って考え方が出てきた。それが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">歴史学派経済学</strong></span>だよ。ドイツの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リスト</strong></span>は、イギリスは先進国だから自由主義を主張するけど、<strong class=\"source-bold\">ドイツは後進国だから保護貿易</strong>でいいんだ！って主張した。この考え方は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ<ruby>関税<rt>かんぜい</rt></ruby>同盟</strong></span>の結成に影響を与えたよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">マルクスの登場。経済学が大きく変わり、社会主義理論も完成！</strong></span></h4>\n<p>ここまで話した経済学は、どれも<strong class=\"source-bold\">資本主義経済のなかでどうするか？</strong>を考えたものだったけど、それを根本からひっくり返したのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス経済学</strong></span>だよ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス</strong></span>はすでに1848年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エンゲルス</strong></span>とともに『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共産党宣言</strong></span>』を発表して、「<strong class=\"source-bold\"><ruby>万国<rt>ばんこく</rt></ruby>の労</strong></p>",
  "118": "<h2>118</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span> 19世紀のヨーロッパ文化</p>\n<p><strong class=\"source-bold\">働者よ、団結せよ</strong>」って主張していたけど、じゃあ「なんで団結するの？」ってことも含めて、マルクスの考え方を解説していこう。</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス</strong></span>は『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">資本論</strong></span>』のなかで<strong class=\"source-bold\">資本主義を分析</strong>して、さっき出てきた労働価値説をさらに突き詰めて<strong class=\"source-bold\"><ruby>剰<rt>じょう</rt></ruby>余価値説</strong>を唱えた。これは教科書みたいな言い方だと「<strong class=\"source-bold\">資本家は労働者に支払う賃金以上の価値を利潤として<ruby>搾取<rt>さくしゅ</rt></ruby>している</strong>」ってことなんだけど……難しい。</p>\n<p>さっきのラーメン屋の話にしよう。ラーメン屋のご主人、1人バイトを雇ってるんだけど、ネギのトッピングを剰余価値説で説明すると、「ラーメン屋のご主人（<strong class=\"source-bold\">資本家</strong>）は、バイトの時給分（<strong class=\"source-bold\">労働者の賃金</strong>）と自分の<ruby>儲<rt>もう</rt></ruby>け（<strong class=\"source-bold\">利潤</strong>）を上乗せして、ネギに150円って値段をつけてる」ってことだ。だから、バイトのおにいちゃんよりもラーメン屋のご主人が儲かる……って当たり前か。バイトより儲からないならラーメン屋やめるよな（笑）。</p>\n<p>これをすべての企業に当てはめれば、<strong class=\"source-bold\">労働者はつねに利潤を上乗せされた値段で物を買わされる</strong>ことになる。だから<strong class=\"source-bold\">労働者は何を買っても搾取され</strong>、いつまでたっても貧乏なままという理論になるでしょ。さらに続きがあって、中小の資本家は大資本家に負けちゃうと労働者に転落するから、資本主義の行きつく先は、<strong class=\"source-bold\">ごく少数の巨大企業（独占資本）が大多数の労働者を搾取する</strong>状態になる。こんなふうにマルクスは<strong class=\"source-bold\">独占資本主義の出現</strong>を予想している。じゃあどうすればいいんだろ？</p>\n<p>マルクスは、人間の能力は時代が進むにつれて発展していくという<strong class=\"source-bold\">ヘーゲルの<ruby>弁<rt>べん</rt></ruby><ruby>証法<rt>しょうほう</rt></ruby>の影響</strong>を受けて、<strong class=\"source-bold\">社会も時代とともに発展</strong>していくという<strong class=\"source-bold\">弁証法的<ruby>唯物論<rt>ゆいぶつろん</rt></ruby></strong>を唱えた。そこから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">史的唯物論</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">唯物史観</strong></span>】に基づき「<strong class=\"source-bold\">資本主義の没落と社会主義への必然的移行</strong>」を主張したよ……今、頭の中がぐちゃぐちゃになったでしょ。教科書で使うような言葉で説明すると難しい。じゃあ、解説しよう。</p>\n<h3><strong class=\"source-bold\">〈マルクスの革命理論〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">〈絶対王政〉</strong></span></td><td><strong class=\"source-bold\">〈資本主義〉</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">〈社会主義〉</strong></span></td></tr><tr><td><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\"><span data-source-cancellation=\"cross\" data-source-cancellation-color=\"brown\" style=\"text-decoration:line-through;text-decoration-color:#a43725\">貴族</span></strong></span></td><td><span data-source-cancellation=\"cross\" data-source-cancellation-color=\"brown\" style=\"text-decoration:line-through;text-decoration-color:#a43725\"><strong class=\"source-bold\">資本家</strong></span></td><td></td></tr><tr><td><strong class=\"source-bold\">階級闘争</strong></td><td><strong class=\"source-bold\">階級闘争</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">労働者</strong></span></span></td></tr><tr><td><strong class=\"source-bold\">平民</strong></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">労働者</strong></span></span></td><td>階級はなくなる</td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ブルジョワ革命</strong></td><td><strong class=\"source-bold\">社会主義革命</strong></td></tr></tbody></table></div>",
  "119": "<h2>119</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">社会科学・哲学</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p>絶対王政の時代には、国王とその周りにいる<strong class=\"source-bold\">貴族が特権を持って平民をいじめる</strong>から、平民たちは豊かになれない。つまり「<strong class=\"source-bold\">貴族」「平民」という階級</strong>があるのが、社会が抱える矛盾なんだよ。そこで、平民が「貴族を<ruby>潰<rt>つぶ</rt></ruby>す！」ってこの矛盾と戦って（これが<strong class=\"source-bold\">階級闘争</strong>だ）、平民を中心とする社会をつくった。これが<strong class=\"source-bold\">ブルジョワ革命【市民革命】</strong>だよ。そうすると<strong class=\"source-bold\">平民を中心とする資本主義の段階に進む</strong>よね。</p>\n<p>じゃあ、資本主義ではみんな幸せになるかっていうと、新しい階級が生まれて、今度は<strong class=\"source-bold\">金持ちの「資本家」が貧乏な「労働者」をいじめる</strong>。労働者たちは「結局貧乏じゃないか！」って思うよね。これが資本主義の抱える矛盾だ。</p>\n<p>そして、資本主義がどんどん発展すると<strong class=\"source-bold\">独占資本主義</strong>になるから、ごく少数の巨大資本家がボロ儲けする。だったら「資本家を潰せ！」ってこの矛盾と戦えば（<strong class=\"source-bold\">新たな階級闘争</strong>だ）、<strong class=\"source-bold\">労働者を中心とする社会</strong>ができる。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会主義革命</strong></span>だよ。ただ労働者一人ひとりは弱いからこれを成功させるためには、世界中の労働者が団結しなきゃいけない。これが「<strong class=\"source-bold\"><ruby>万国<rt>ばんこく</rt></ruby>の労働者よ、団結せよ！</strong>」ってことね。</p>\n<p>こうして、一番貧乏な<strong class=\"source-bold\">労働者階級が政権を取れば平等な社会ができる</strong>。これがマルクスの<strong class=\"source-bold\">革命理論</strong>だよ。ザックリとらえると、「<strong class=\"source-bold\">絶対王政から2回の革命（ブルジョワ革命と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会主義革命</strong></span>）をやると社会主義になる</strong>」ってことね。</p>\n<h3><strong class=\"source-bold\">〈古典派経済学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>英</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルサス</strong></span></td><td>『<strong class=\"source-bold\">人口論</strong>』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リカード</strong></span></td><td><strong class=\"source-bold\">労働価値説</strong>。『経済学および課税の原理』</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈歴史学派経済学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>独</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リスト</strong></span></td><td><strong class=\"source-bold\">保護貿易主義</strong>を主張。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ<ruby>関税<rt>かんぜい</rt></ruby>同盟</strong></span>の結成に影響</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈マルクス経済学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>独</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス</strong></span></td><td>『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">資本論</strong></span>』。<strong class=\"source-bold\">剰余価値説</strong>から資本主義を分析<br>哲学では<strong class=\"source-bold\">弁証法的唯物論</strong>。歴史学では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">史的唯物論</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">唯物史観</strong></span>】を創始</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エンゲルス</strong></span></td><td>『イギリスにおける労働者階級の状態』</td></tr></tbody></table></div>\n<h4><em data-source-italic=\"true\" style=\"font-style:italic\"><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">その他の社会科学</strong></span></em></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">民族の独自性を追求したドイツ人は、歴史が大好き！</strong></span></h4>\n<p><strong class=\"source-bold\">ロマン主義の風潮</strong>によって、各個人の個性や民族の伝統を重視しようって考え方が広がると、特に<strong class=\"source-bold\">ドイツ</strong>では「じゃあ、伝統とはなんだろ？」って<strong class=\"source-bold\">歴史を探ろうとする動き</strong>が出てきた。まず<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ランケ</strong></span>は残された<strong class=\"source-bold\">史料をきちんと分析</strong>して事実を探り、「本来それがどうであったか」を書くのが歴史であるという<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">近代歴史学</strong></span>を確立した</p>",
  "120": "<h2>120</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span> 19世紀のヨーロッパ文化</p>\n<p>よ。彼は「各民族にはそれぞれに“良さ”や“独自性”がある」と考えて、歴史における民族の個性や多様性を重視したよ。この影響で他の社会科学の分野では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サヴィニー</strong></span>が「各民族がたどってきた歴史によって、<strong class=\"source-bold\">各民族固有の法がある</strong>」という<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">歴史法学</strong></span>を創始したんだ。これも、<strong class=\"source-bold\">自由主義を進めるイギリス</strong>に対して、「ドイツは多少法律が厳しくても、自由が制限されててもいいんだ〜！」って言いたいんだろうけどね。この考え方が、プロイセンの憲法やドイツの民法典に影響したんだ。</p>\n<h3><strong class=\"source-bold\">〈その他社会科学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>独</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ランケ</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">近代歴史学</strong></span>を確立。『世界史』</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サヴィニー</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">歴史法学</strong></span>を創始。『中世ローマ法史』</td></tr></tbody></table></div>\n<h4><em data-source-italic=\"true\" style=\"font-style:italic\"><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">哲学</strong></span></em></h4>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">市民社会が成熟したイギリスでは「最大多数の最大幸福」を目指す</strong></span></h4>\n<p>資本主義が発展した<strong class=\"source-bold\">イギリス</strong>では、産業資本家が台頭して地主と対立し、さらに労働者の生活環境や労働環境が問題になっていたよね。こうしたことを背景に、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベンサム</strong></span>は「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">最大多数の最大幸福</strong></span>」を主張する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>功利<rt>こうり</rt></ruby>主義</strong></span>を打ち出した。これは当時発言力が大きくなっていた産業資本家を中心とする<strong class=\"source-bold\">ブルジョワ階級の主張と一致</strong>するよね。これを一歩進めたのは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョン＝ステュアート＝ミル</strong></span>の<strong class=\"source-bold\">社会改良主義</strong>だ。議会に進出していない労働者や女性は自分たちの権利を主張する場所もないのだから（だって参政権がないよね）、権利がある人たちが進んで<strong class=\"source-bold\">社会を改良して幸福の質を高め、理想的な社会をつくらなければいけない</strong>、って主張したよ。また<strong class=\"source-bold\">ハーバート＝スペンサー</strong>は進化論を社会に当てはめ、優れた社会（国）は勝ち、劣った社会（国）は敗れるという<strong class=\"source-bold\">社会進化論</strong>を主張したんだよ。社会進化論は、<strong class=\"source-bold\">フランス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コント</strong></span>が主張した「現実の経験によって確かめたことからしか知識は得られない」とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">実証主義</strong></span>の影響も受けているよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「神は死んだ」と叫んだニーチェ。実存主義ってなんだろう？</strong></span></h4>\n<p>ヨーロッパの文化史をやると、どうしてもぶち当たるのが「<strong class=\"source-bold\">キリスト教」の問題</strong>……。絶対神、創造神、唯一神……どれも日本の宗教にはない感覚だ。<strong class=\"source-bold\">キリスト教</strong>では、「<strong class=\"source-bold\">この世界はすべて神の創造物だから、神の思うようになっている</strong>」っていうのが大前提なんだよ。だから人間が何をしようと神の意志にはかなわないし、そもそも神がなんなのかさえ知ることもできない。最終的に救われるかどうかも神が決める。だったら無条件に神を信仰して、「信仰すれば救われる」と思えばいい。全部神が決めることだから、「<strong class=\"source-bold\">とにかく信じるしかない</strong>」ということになる。</p>\n<p>でも、そう割り切れない人もいるよね。<strong class=\"source-bold\">ショーペンハウエル</strong>は、人生の本質は「<strong class=\"source-bold\">盲目的な生への意思</strong>（ずっと生きたいと思うこと）」と考えた。人は必ず訪れる死への不安から逃れることはできず、人生は苦そのものである、ってことね。これが</p>",
  "121": "<h2>121</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">6</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">自然科学・科学技術</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<p><strong class=\"source-bold\"><ruby>厭世<rt>えんせい</rt></ruby>哲学【ペシミズム】</strong>だ。こう考え始めたら、何をやっても絶対楽しくない。これ、<strong class=\"source-bold\">インド思想の影響</strong>だよ。インド思想も「生＝苦」というのが基本だ。</p>\n<p>また、<strong class=\"source-bold\">デンマーク</strong>の<strong class=\"source-bold\">キェルケゴール</strong>は「<strong class=\"source-bold\">つねに神の前にいることの不安</strong>（いつも神に見られているってことね）」を哲学に高め、「いかにして神の前に一人で立つキリスト者となるか」、つまり自分を一人の主体的な人間と考えて、<strong class=\"source-bold\">どのように神と向き合うべきか</strong>（人と人が向き合うように1対1で神と向き合う）、を追及したよ。これらの哲学を<strong class=\"source-bold\">実存主義</strong>というんだ。</p>\n<p>こうした思想の影響を受け、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニーチェ</strong></span>は「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">神は死んだ</strong></span>」と主張した。はっきり言ってニーチェはよくわからん。彼の出発点は<strong class=\"source-bold\">ニヒリズム</strong>（権威や権力はすべて意味のないいらないものという発想）で、これをどう克服するかが問題だった。だって、<strong class=\"source-bold\">弱い人間を救うはずのキリスト教</strong>の考え方（道徳観）も、実は<strong class=\"source-bold\">弱者に都合のいいように創作されている</strong>から、神だって本当に救ってはくれない。だから「神は死んだ」として一人ひとりが「<strong class=\"source-bold\"><ruby>超人<rt>ちょうじん</rt></ruby></strong>」となって<strong class=\"source-bold\">ニヒリズムを克服</strong>しなければいけないと説いた。さらに世界の出来事は、<strong class=\"source-bold\">何一つ変わらず永遠に繰り返される</strong>（<strong class=\"source-bold\"><ruby>永劫回<rt>えいごうかい</rt></ruby><ruby>帰<rt>き</rt></ruby></strong>）のだから、喜びも苦悩も含めた<strong class=\"source-bold\">現実の生をそのまま肯定して受け入れるべき</strong>、と主張した。ここまで説明しても、やっぱりわからん。だって、<strong class=\"source-bold\">ニーチェ本人も最後は発狂</strong>しているんだもん。入試では「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">神は死んだ</strong></span>」「<strong class=\"source-bold\">超人</strong>」「<strong class=\"source-bold\">永劫回帰</strong>」「<strong class=\"source-bold\">力への意思</strong>」っていうキーワードを覚えておけばOKだ。</p>\n<h3><strong class=\"source-bold\">〈哲学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>英</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベンサム</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">功利主義</strong></span>。「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">最大多数の最大幸福</strong></span>」</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョン＝ステュアート＝ミル</strong></span></td><td><strong class=\"source-bold\">社会改良主義</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">ハーバート＝スペンサー</strong></td><td><strong class=\"source-bold\">社会進化論</strong></td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コント</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">実証主義</strong></span>。<strong class=\"source-bold\">社会学の祖</strong></td></tr><tr><td>独など</td><td><strong class=\"source-bold\">ショーペンハウエル</strong></td><td><strong class=\"source-bold\">厭世哲学【ペシミズム】</strong></td></tr><tr><td></td><td><strong class=\"source-bold\">キェルケゴール</strong></td><td>デンマークの哲学者。<strong class=\"source-bold\">実存主義の先駆者</strong></td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニーチェ</strong></span></td><td>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">神は死んだ</strong></span>」「<strong class=\"source-bold\">超人</strong>」「<strong class=\"source-bold\">永劫回帰</strong>」「<strong class=\"source-bold\">力への意思</strong>」</td></tr></tbody></table></div>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">6</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">自然科学・科学技術</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">科学技術のもとになった発見がいっぱいだ！</strong></span></h4>\n<p>19世紀前半の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次産業革命</strong></span>は<strong class=\"source-bold\">石炭と蒸気（蒸気機関）</strong>によって産業が発展したけど、19世紀後半には<strong class=\"source-bold\">石油と電力</strong>を動力とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次産業革命</strong></span>が進み、一気に<strong class=\"source-bold\">科学技術の時代</strong>になった。背景には、当時の<strong class=\"source-bold\">物理学や化学</strong>における発見があるよ。</p>\n<p>まず、<strong class=\"source-bold\">イギリス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファラデー</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">電磁誘導の法則</strong></span>や電気分解の法則を発見して<strong class=\"source-bold\">電磁気学</strong>が発展し、さらに<strong class=\"source-bold\">ドイツ</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マイヤー</strong></span>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヘルムホルツ</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エネルギー保存の法則</strong></span>を</p>",
  "122": "<h2>122</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span> 19世紀のヨーロッパ文化</p>\n<p>発見して、<strong class=\"source-bold\">熱力学</strong>が発展したよ。こうして発見された法則は科学技術の発展に応用され、<strong class=\"source-bold\">ジーメンス</strong>が<strong class=\"source-bold\">発電機</strong>を実用化して<strong class=\"source-bold\">電機産業</strong>が発展し、<strong class=\"source-bold\">ダイムラー</strong>や<strong class=\"source-bold\">ディーゼル</strong>による<strong class=\"source-bold\">エンジン（ガソリン機関やディーゼル機関）</strong>の発明で、<strong class=\"source-bold\">自動車</strong>が作られるようになった。また、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レントゲン</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">X放射線</strong></span>を、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キュリー夫妻</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラジウム</strong></span>を発見するなど、放射線や放射性物質の発見が続き、<strong class=\"source-bold\">医療技術</strong>などに応用された。さらに<strong class=\"source-bold\">リービヒ</strong>による<strong class=\"source-bold\">有機化学</strong>の確立で、<strong class=\"source-bold\">化学工業</strong>も発展していくんだ。</p>\n<p>生物学や医学の発達もいろいろあるよ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パストゥール</strong></span>の<strong class=\"source-bold\"><ruby>狂犬病<rt>きょうけんびょう</rt></ruby>の予防接種</strong>や、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コッホ</strong></span>の<strong class=\"source-bold\">コレラ菌・<ruby>結核菌<rt>けっかくきん</rt></ruby>の発見</strong>で病気の予防や治療の幅が広がり、<strong class=\"source-bold\"><ruby>細菌学<rt>さいきんがく</rt></ruby></strong>も発展し始めた。また、<strong class=\"source-bold\">メンデル</strong>の<strong class=\"source-bold\"><ruby>遺伝<rt>いでん</rt></ruby>の法則</strong>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダーウィン</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">進化論</strong></span>は、生物学にとどまらず<strong class=\"source-bold\">社会科学や宗教にも大きな影響を与える</strong>ことになるよ。だって、進化論は「神は人間を創造した」というキリスト教の教義を根本からひっくり返す考え方でしょ？ こりゃ大事件だよ。</p>\n<p>最後に<strong class=\"source-bold\">情報通信</strong>ね。19世紀以前には<strong class=\"source-bold\">情報が伝わる速度と人が移動する速度は一緒</strong>だった。だって手紙しかないんだもん。現代はインターネット上で全世界に一瞬で情報を送れるし、それこそ何かしらのアプリをインストールすれば、全世界とタダでテレビ電話もできる時代だもんね。でも昔は人が運ぶ手紙しか情報を伝える手段はなかったんだ。それを劇的に変えたのが、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モース</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モールス</strong></span>】による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">電信機</strong></span>の発明だよ。映画とかで見たことないかな？ 「トン・トン・ツー……」みたいな感じで、電気が流れると音が鳴る仕組みで、暗号にした文字を読み取るだけの簡単なものだけど、当時としては劇的な変化だよ。だって<strong class=\"source-bold\">一瞬で情報を送れる</strong>んだもん、それだけですごい！ そして、各地で<strong class=\"source-bold\">電信線</strong>が敷かれ始めた。最初は<strong class=\"source-bold\">アメリカのワシントンからボルティモア</strong>に敷かれたんだけど、そこから10年経たないうちに<strong class=\"source-bold\">英仏間のドーヴァー海峡</strong>（1851）に、さらに<strong class=\"source-bold\">大西洋</strong>（1866）や<strong class=\"source-bold\">イギリス〜インド間</strong>（1870）に<strong class=\"source-bold\">海底電信ケーブル</strong>が敷かれ、<strong class=\"source-bold\">情報による世界の一体化</strong>が進んだよ。</p>\n<p>さらに<strong class=\"source-bold\">アメリカ</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベル</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">電話機</strong></span>を発明すると、離れたところと会話ができるようになり、もうびっくりなんてもんじゃない。そして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルコーニ</strong></span>の発明した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">無線電信</strong></span>と合わせれば……ほら、今みんなが使っているスマホの通信だって、この無線電信技術が進歩したものだ。このあたりの発明は、今のみんなの生活にもかかわるようなものがいくつもあるね。</p>",
  "123": "<h2>123</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">6</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">自然科学・科学技術</u></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民国家の形成</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>\n<h3><strong class=\"source-bold\">〈物理学・化学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>英</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファラデー</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">電磁誘導の法則</strong></span>。電気分解の法則。<strong class=\"source-bold\">電磁気学</strong>の発展</td></tr><tr><td>独</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マイヤー</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エネルギー保存の法則</strong></span>。<strong class=\"source-bold\">熱力学</strong>の発展</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヘルムホルツ</strong></span></td><td></td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レントゲン</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">X放射線</strong></span>の発見。<strong class=\"source-bold\">第1回ノーベル物理学賞</strong>を受賞</td></tr><tr><td></td><td><strong class=\"source-bold\">リービヒ</strong></td><td><strong class=\"source-bold\">有機化学の基礎</strong>を確立。化学工業や化学肥料</td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キュリー夫妻</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラジウム</strong></span>の発見。妻はポーランド出身</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈生物学・医学〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>英</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダーウィン</strong></span></td><td>『<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">種の起源</strong></span>』。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">進化論</strong></span>を発表</td></tr><tr><td>仏</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パストゥール</strong></span></td><td><ruby>乳酸菌<rt>にゅうさんきん</rt></ruby>の発見。<strong class=\"source-bold\">狂犬病の予防接種</strong>に成功</td></tr><tr><td>独</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コッホ</strong></span></td><td><strong class=\"source-bold\">結核菌、コレラ菌の発見</strong>。ツベルクリンを創設。<strong class=\"source-bold\">細菌学</strong>の発展</td></tr><tr><td>墺</td><td><strong class=\"source-bold\">メンデル</strong></td><td>遺伝の法則</td></tr></tbody></table></div>\n<h3><strong class=\"source-bold\">〈科学技術〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>英</td><td>ベッセマー</td><td><ruby>転炉<rt>てんろ</rt></ruby>による製鋼法の発明</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ノーベル</strong></span></td><td><em data-source-italic=\"true\" style=\"font-style:italic\"><strong class=\"source-bold\">スウェーデン人</strong></em>。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダイナマイト</strong></span>、無煙火薬の発明</td></tr><tr><td>米</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モース</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">電信機</strong></span>の発明。モールス信号</td></tr><tr><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベル</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">電話機</strong></span>の発明</td></tr><tr><td>伊</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルコーニ</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">無線電信</strong></span>の発明</td></tr><tr><td>米</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エディソン</strong></span></td><td><strong class=\"source-bold\"><ruby>蓄音機<rt>ちくおんき</rt></ruby>、白熱電球、映画など</strong>を発明。「<strong class=\"source-bold\">発明王</strong>」</td></tr><tr><td>独</td><td><strong class=\"source-bold\">ダイムラー</strong></td><td><strong class=\"source-bold\">ガソリン機関（エンジン）</strong>の発明。<strong class=\"source-bold\">自動車</strong>を製作</td></tr><tr><td></td><td><strong class=\"source-bold\">ディーゼル</strong></td><td><strong class=\"source-bold\">ディーゼル機関（エンジン）</strong>の発明</td></tr><tr><td></td><td><strong class=\"source-bold\">ジーメンス</strong></td><td><strong class=\"source-bold\">発電機</strong>、モーターの実用化。電車の発明</td></tr></tbody></table></div>\n<p>さて、19世紀のヨーロッパ文化史どうだった？ 単なる名前の丸暗記じゃなくて、同じ時代の政治とか社会とつなげてみると、また違った見方ができるようになるよ。</p>\n<p>今回は文化史だから年号checkはなしだよ。</p>\n<p><strong class=\"source-bold\">次回からはアジア近現代史</strong>だ。今回までのヨーロッパ史とつながるところもいっぱいあるから、きっちり復習して次に進んでね。</p>",
  "124": "<h2>124</h2>"
};

